public function applyFilters(Builder $query, array $filters): void
{
    $query->whereNull('registry_records.deleted_at');
    if ($filters['from'] !== null || $filters['until'] !== null) {
        $fromUtc = $filters['from_utc'] === null ? null
            : ClinicAppointmentTime::queryTimestamp($query, new DateTimeImmutable($filters['from_utc']));
        $untilUtc = $filters['until_utc'] === null ? null
            : ClinicAppointmentTime::queryTimestamp($query, new DateTimeImmutable($filters['until_utc']));
        $query->where(static function (Builder $dates) use ($filters, $fromUtc, $untilUtc): void {
            $dates->where(static function (Builder $known) use ($fromUtc, $untilUtc): void {
                $known->whereNotNull('appointment_starts_at_utc');
                if ($fromUtc !== null) $known->where('appointment_starts_at_utc', '>=', $fromUtc);
                if ($untilUtc !== null) $known->where('appointment_starts_at_utc', '<', $untilUtc);
            })->orWhere(static function (Builder $legacy) use ($filters): void {
                $legacy->whereNull('appointment_starts_at_utc');
                if ($filters['from'] !== null) $legacy->where('for_datetime', '>=', $filters['from']);
                if ($filters['until'] !== null) $legacy->where('for_datetime', '<', $filters['until']);
            });
        });
    }
    if ($filters['format'] !== 'all') $query->where('appointment_format', $filters['format']);
    $query->reorder();
    ClinicAppointmentTime::orderByStart($query, $filters['direction']);
}

